  const $ = s => document.querySelector(s);
  const inp=$('#inp'), strip=$('#strip'), mono=$('#mono');
  const plain = s => s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').normalize('NFC');
  const key = s => plain(s).toLowerCase().replace(/ς/g,'σ');
  const withoutAccent = s => s.normalize('NFD').replace(/[\u0300\u0301\u0342]/g,'');
  const monotonic = s => s.normalize('NFD').replace(/[\u0300\u0342]/g,'\u0301').replace(/[\u0313\u0314\u0345]/g,'').normalize('NFC');
  const examples=['Καρνος','Αορνος','Σαμορνος','Φαλερνος','Λιβυρνος','Αχαρνος','Γοννοι'];
  const sourceForms=['Κάρνος','Ἄρνος','Νάρνος','Κύρνος','Πύρνος','Σάμορνος','Ἄορνος','Λιβυρνός','Ἀχαρνός','Φαλέρνος','πατέρνος','Ἰουέρνος','Ἀροέρνος','Πριουέρνος','Γόννοι','Σίγυννος','Τυρρηνός','Τυρρανός'];
  const lexicon=new Map(sourceForms.map(form=>[key(form),form]));
  // Demonstration only: group common diphthongs, respecting written diaeresis.
  function forceAccent(raw,fromEnd){
    const chars=Array.from(withoutAccent(raw));
    const vowels=[];
    for(let i=0;i<chars.length;i++){
      if(!/[αεηιουω]/i.test(chars[i])) continue;
      let next=i+1;
      while(next<chars.length && /[\u0300-\u036f]/.test(chars[next])) next++;
      const pair=(chars[i]+(chars[next]||'')).toLowerCase();
      let marked=next+1;
      while(marked<chars.length && /[\u0300-\u036f]/.test(chars[marked])) marked++;
      if(['αι','ει','οι','υι','αυ','ευ','ηυ','ου'].includes(pair) && !chars.slice(next+1,marked).includes('\u0308')){
        vowels.push(next);i=next;
      }else vowels.push(i);
    }
    const target=vowels[vowels.length-fromEnd];
    if(target===undefined) return raw;
    let end=target+1;
    while(end<chars.length && /[\u0300-\u036f]/.test(chars[end])) end++;
    chars.splice(end,0,'\u0301');
    const out=chars.join('').normalize('NFC');
    return mono.checked ? monotonic(out) : out;
  }
  function clear(message='—'){
    $('#noticed').textContent=message;
    ['suggest','forced','nn'].forEach(id=>$('#'+id).textContent='—');
    $('#nnWhy').textContent='';
  }
  function render(){
    const raw=inp.value.trim();
    if(!raw){clear();return;}
    if(!/^[\p{Script=Greek}\p{M}]+$/u.test(raw)){
      clear('Enter one Greek word. Phrases and non-Greek input are outside this toy.');return;
    }
    const k=key(raw), known=lexicon.get(k);
    let reason='No attested form in this selection; no accent prediction is made.';
    if(known && (k===key('Λιβυρνος') || k===key('Αχαρνος'))) reason='Named oxytone exception to the -ρνος tendency in this passage.';
    else if(known && k.endsWith('ερνοσ')) reason='The passage’s -ερνος group is paroxytone (penult acute).';
    else if(known && k.endsWith('ρνοσ')) reason='The -ρνος group is barytone: accent is not final. The attested position is shown, rather than guessing the penult.';
    else if(known) reason='Attested spelling and accent from this passage.';
    const hasAccent=/[\u0300\u0301\u0342]/.test(raw.normalize('NFD'));
    let form=known || raw;
    if(!strip.checked && hasAccent){form=raw;reason+=' Existing input accent retained by your option.';}
    if(mono.checked) form=monotonic(form);
    $('#noticed').textContent=reason;
    $('#suggest').textContent=form;
    $('#forced').textContent=form;
    // The passage supports Γόννοι specifically, not a productive -νοι doubling rule.
    if(k===key('Γονοι') || k===key('Γοννοι')){
      $('#nn').textContent='Γόννοι';
      $('#nnWhy').textContent='The city Γόννοι has νν; Herodian compares Aeolic γόννα, “knees”. This is a specific example, not a general spelling rule.';
    }else{
      $('#nn').textContent=raw;
      $('#nnWhy').textContent='No ν is added. The passage supports the city Γόννοι specifically.';
    }
  }
  $('#btn').addEventListener('click',render);
  inp.addEventListener('keydown',e=>{if(e.key==='Enter') render();});
  strip.addEventListener('change',render);mono.addEventListener('change',render);
  $('#btnRand').addEventListener('click',()=>{inp.value=examples[Math.floor(Math.random()*examples.length)];render();});
  $('#reset').addEventListener('click',()=>{inp.value='';strip.checked=true;mono.checked=false;render();inp.focus();});
  document.querySelectorAll('[data-force]').forEach(button=>button.addEventListener('click',()=>{
    const raw=inp.value.trim();
    if(raw && /^[\p{Script=Greek}\p{M}]+$/u.test(raw)) $('#forced').textContent=forceAccent(raw,{ult:1,pen:2,ant:3}[button.dataset.force]);
  }));
  inp.value='Καρνος';render();
})();

